const cfg = $('Config: Parametros del Sistema').first().json;
const lead = $('Normalizar y Validar Lead').first().json;
const resp = $input.first().json;
const raw = (((resp.content || []).find(b => b && b.type === 'text') || {}).text) || '';
const clean = raw.replace(/```json|```/g, '').trim();
const a = clean.indexOf('{');
const b = clean.lastIndexOf('}');
if (a === -1 || b === -1) { throw new Error('La IA no devolvio un JSON valido'); }
const p = JSON.parse(clean.slice(a, b + 1));
const clamp = (v, max) => Math.max(0, Math.min(max, Number(v) || 0));
const cargo = clamp(p.puntaje_cargo, 20);
const urgencia = clamp(p.puntaje_urgencia, 20);
const presupuesto = lead.presupuesto_estimado_usd >= Number(cfg.presupuesto_alto_usd) ? 30 : (lead.presupuesto_estimado_usd >= Number(cfg.presupuesto_medio_usd) ? 15 : 0);
const tamano = lead.tamano_empresa_empleados >= Number(cfg.empleados_alto) ? 20 : (lead.tamano_empresa_empleados >= Number(cfg.empleados_medio) ? 10 : 0);
const score = cargo + urgencia + presupuesto + tamano;
const categoria = score >= Number(cfg.umbral_vip) ? 'VIP' : (score >= Number(cfg.umbral_calificado) ? 'Calificado' : 'Descarte');
const razon = Array.isArray(p.razonamiento_paso_a_paso) ? p.razonamiento_paso_a_paso.join(' | ') : String(p.razonamiento_paso_a_paso || '');
const detalle = 'Cargo ' + cargo + '/20, Urgencia ' + urgencia + '/20, Presupuesto ' + presupuesto + '/30, Tamano ' + tamano + '/20. ' + razon;
return [{ json: { score_total: score, categoria, razonamiento: detalle, tokens_entrada: (resp.usage && resp.usage.input_tokens) || 0, tokens_salida: (resp.usage && resp.usage.output_tokens) || 0, modelo: resp.model || cfg.modelo_clasificacion } }];

const resp = $input.first().json;
const raw = (((resp.content || []).find(b => b && b.type === 'text') || {}).text) || '';
const clean = raw.replace(/```json|```/g, '').trim();
const a = clean.indexOf('{');
const b = clean.lastIndexOf('}');
if (a === -1 || b === -1) { throw new Error('La IA no devolvio un JSON valido para el borrador'); }
const p = JSON.parse(clean.slice(a, b + 1));
if (!p.asunto || !p.cuerpo) { throw new Error('El borrador no trae asunto o cuerpo'); }
return [{ json: { asunto: String(p.asunto), cuerpo: String(p.cuerpo) } }];

const mail = $('Config: Parametros del Sistema').first().json;
const resp = $input.first().json;
const fromObj = (mail.from && mail.from.value && mail.from.value[0]) || {};
const address = String(fromObj.address || '').toLowerCase();
const nombreFb = String(fromObj.name || '').trim() || (address ? address.split('@')[0] : '');
const subject = String(mail.subject || '');
const body = String(mail.text || mail.snippet || '');
let p = null;
try {
  const raw = (((resp.content || []).find(b => b && b.type === 'text') || {}).text) || '';
  const clean = raw.replace(/```json|```/g, '').trim();
  const a = clean.indexOf('{');
  const b = clean.lastIndexOf('}');
  if (a !== -1 && b !== -1) { p = JSON.parse(clean.slice(a, b + 1)); }
} catch (e) { p = null; }
const fallo = p === null || typeof p.es_consulta_relevante === 'undefined';
p = p || {};
const relevante = !fallo && (p.es_consulta_relevante === true || String(p.es_consulta_relevante).toLowerCase() === 'true');
const str = (v, fb) => { const s = String(v == null ? '' : v).trim(); return s || fb; };
const num = (v) => Math.max(0, Number(v) || 0);
return [{ json: { es_relevante: relevante, clasificacion_fallida: fallo, motivo_relevancia: str(p.motivo_relevancia, fallo ? 'no se pudo clasificar' : ''), remitente: address, asunto: subject, nombre: str(p.nombre, nombreFb), email: address, empresa: str(p.empresa, 'No especificado'), cargo: str(p.cargo, 'No especificado'), telefono: str(p.telefono, ''), mensaje: (subject + '\n' + body).slice(0, 4000), presupuesto_estimado_usd: num(p.presupuesto_estimado_usd), tamano_empresa_empleados: num(p.tamano_empresa_empleados), fuente: 'Otro', origen: 'correo' } }];
